import {foods,plan} from './model.js';
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD'}).format(n/100);
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
function request(action,planData){return new Promise((resolve,reject)=>{const id=crypto.randomUUID();const timer=setTimeout(()=>{window.removeEventListener('message',onMessage);reject(new Error('The companion is not enabled in this browser. Follow the setup steps below.'));},2200);function onMessage(e){if(e.source!==window||e.origin!==location.origin||e.data?.channel!=='assembl.woolworths.response'||e.data.id!==id)return;clearTimeout(timer);window.removeEventListener('message',onMessage);e.data.ok?resolve(e.data.data):reject(new Error(e.data.error||'Connection unavailable.'));}window.addEventListener('message',onMessage);window.postMessage({channel:'assembl.woolworths.request',id,action,plan:planData},location.origin);});}
export function initWoolworths(getState,toast){
 let linked=false,busy=false;
 const status=text=>$('#wwStatus').textContent=text;
 function shops(){const p=plan(getState());const select=$('#wwShop');const previous=select.value;select.replaceChildren();for(const s of p.shops){const o=node('option',s.day+' · '+(s.kind==='main'?'main shop':'fresh top-up')+' · '+s.items.length+' lines');o.value=s.kind;select.append(o);}if([...select.options].some(x=>x.value===previous))select.value=previous;}
 function render(data){linked=!!data.linked;$('#wwConnected').dataset.linked=String(linked);$('#wwConnected').textContent=linked?'Browser linked · login stays with Woolworths NZ':'Browser companion not connected';$('#wwSend').disabled=!linked;$('#wwOpen').disabled=!linked;$('#wwDisconnect').hidden=!linked;$('#wwSetup').open=!linked;$('#wwRecords').replaceChildren();
  if(data.records?.length){$('#wwRecords').append(node('h3','Your Woolworths NZ trolley record'));for(const r of data.records){const q=r.quote;if(!q)continue;const item=node('div',undefined,'nw-record');item.append(node('strong',q.name),node('span',`${q.quantity} ${q.unit} · ${money(Math.round(q.priceCents*q.quantity))} at displayed price`),node('small',`${q.store} · read ${new Date(q.observedAt).toLocaleString('en-NZ')}`),node('small',r.status==='verified'?'Observed in trolley':r.status==='customer-confirmed'?'Confirmed by you':'Result needs a trolley check'));$('#wwRecords').append(item);}$('#wwRecords').append(node('p','These are product snapshots, not a final order total. Recheck prices, offers, weight, substitutions and fees at Woolworths NZ checkout.','small-copy'));}
 }
 async function refresh(){try{const data=await request('status');render(data);status(data.linked?'Ready to send one planned shop for product matching.':'Open the companion and enable browser access.');}catch(e){render({linked:false});status(e.message);}}
 $('#woolworthsConnect').onclick=()=>{shops();$('#woolworthsDialog').showModal();refresh();};
 $('#wwRefresh').onclick=refresh;
 $('#wwOpen').onclick=async()=>{try{await request('open');status('The shopping companion is open in your browser.');}catch(e){status(e.message);}};
 $('#wwSend').onclick=async()=>{if(busy)return;const s=plan(getState()).shops.find(x=>x.kind===$('#wwShop').value);if(!s?.items.length)return status('This shop has no ingredients to buy.');busy=true;$('#wwSend').disabled=true;try{await request('prepare',{type:'assembl.woolworths.plan',version:1,day:s.day,kind:s.kind,items:s.items.map(x=>({id:x.id,name:foods.find(f=>f.id===x.id).name,quantity:x.qty,unit:foods.find(f=>f.id===x.id).unit}))});status('List sent to your local companion. Accept the list there, choose products, then approve one fixed-price pack and check the trolley result.');toast('Woolworths NZ plan sent for your review.');}catch(e){status(e.message);}finally{busy=false;$('#wwSend').disabled=!linked;}};
 $('#wwDisconnect').onclick=async()=>{try{await request('disconnect');render({linked:false});status('Disconnected. Shopping records and website permissions were cleared.');}catch(e){status(e.message);}};
 $('#erase').addEventListener('click',()=>request('disconnect').catch(()=>{}));
 window.addEventListener('focus',()=>{if($('#woolworthsDialog').open)refresh();});
}
